update public.products set description='Whole processed goat head containing edible head meat and associated tissues, traditionally used for dishes such as Isi Ewu, pepper soup and other thoroughly cooked goat preparations.', handling_protocols=array['Keep goat head continuously chilled or frozen until preparation.','Handle on dedicated clean surfaces and prevent raw juices from contaminating produce and cooked foods.','Clean individual edible portions as required while minimising splashing.','Cook edible portions thoroughly; a conservative target is at least 71°C / 160°F.']::text[], storage_tips=array['Refrigerate at 4°C or below and use within 1–2 days.','For longer storage, freeze at about -18°C or below and use within about 3–4 months for best quality.']::text[] where name='Goat Head' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
